```python
def valid_brackets(s: str) -> bool:
    """Return True if all (), [], and {} brackets in s are correctly matched and nested."""
    pairs = {")": "(", "]": "[", "}": "{"}
    opening = set(pairs.values())
    stack = []

    for char in s:
        if char in opening:
            # Track opening brackets until their matching closers appear.
            stack.append(char)
        elif char in pairs:
            # A closing bracket must match the most recent opening bracket.
            if not stack or stack.pop() != pairs[char]:
                return False

    # Valid only if no opening brackets remain unmatched.
    return not stack
```

```python
def flatten(nested: list) -> list:
    """Return a new flat list of all non-list elements in left-to-right order."""
    flat = []
    stack = [iter(nested)]

    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            # Finished the current list; return to its parent.
            stack.pop()
            continue

        if type(item) is list:
            # Descend into lists only; keep tuples, strings, etc. as values.
            stack.append(iter(item))
        else:
            flat.append(item)

    return flat
```

