def leftmost_index(arr: list[int], target: int) -> int:
    """Return the index of the first occurrence of target in sorted arr, or -1."""
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            result = mid          # Record match and keep searching left
            right = mid - 1
        elif arr[mid] < target:
            left = mid + 1        # Target must be to the right
        else:
            right = mid - 1       # Target must be to the left

    return result
```

```python
def longest_common_subsequence(a: str, b: str) -> int:
    """Return the length of the longest common subsequence of strings a and b.

    Uses dynamic programming with O(min(len(a), len(b))) extra memory.
    """
    # Use the shorter string for the DP row to minimize memory usage.
    if len(a) < len(b):
        short, long = a, b
    else:
        short, long = b, a

    dp = [0] * (len(short) + 1)

    for ch_long in long:
        # prev holds the diagonal value from the previous row: dp[j - 1].
        prev = 0
        for j, ch_short in enumerate(short, start=1):
            temp = dp[j]
            if ch_long == ch_short:
                dp[j] = prev + 1
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = temp

    return dp[-1]
```

```python
import heapq


def shortest_paths(graph: dict[str, list[tuple[str, int]]], source: str) -> dict[str, int]:
    """Return shortest-path distances from source using Dijkstra's algorithm."""
    distances: dict[str, int] = {source: 0}
    heap: list[tuple[int, str]] = [(0, source)]

    while heap:
        current_dist, node = heapq.heappop(heap)

        # Skip stale heap entries that are no longer the best known distance.
        if current_dist != distances[node]:
            continue

        # Use an empty list for nodes that appear only as neighbors.
        for neighbor, weight in graph.get(node, []):
            new_dist = current_dist + weight

            # Relax the edge if a shorter path to the neighbor is found.
            if neighbor not in distances or new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                heapq.heappush(heap, (new_dist, neighbor))

    return distances
```
